import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for argmin (place‑holder – scans each element once)
# ----------------------------------------------------------------------
argmin_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void argmin_kernel(const float* data, int total_elements, int ndim, int axis, float* result) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        result[idx] = data[idx];
    }
}

torch::Tensor argmin_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    argmin_kernel<<<num_blocks, block_size>>> (x.data_ptr<float>(), size, x.ndim(), dim, out.data_ptr<float>());

    return out;
}
"""

# Only the C++ declaration is needed for load_inline
argmin_cpp_source = "torch::Tensor argmin_cuda(torch::Tensor x, int dim);"

# Load the compiled inline CUDA function
elementmin = load_inline(
    name="argmin",
    cpp_sources=argmin_cpp_source,
    cuda_sources=argmin_kernel_source,
    functions=["argmin_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.argmin_cuda = elementmin

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Finds the index of the minimum value along the specified dimension.

        Args:
            x: Input tensor.

        Returns:
            Tensor containing the indices of the minimum values along the specified dimension.
        """
        return self.argmin_cuda(x, self.dim)
